mapper.select:
SELECT a.co_id, a.co_nm, COALESCE(a.co_eng_nm, '') AS co_eng_nm, COALESCE(a.co_biz_no, '') AS co_biz_no, COALESCE(a.co_no, '') AS co_no, COALESCE(a.co_rep_nm, '') AS co_rep_nm, COALESCE(a.co_ttl_emp_no, 0) AS co_ttl_emp_no, COALESCE(a.co_est_fom, '') AS co_est_fom, COALESCE(to_char(a.co_est_dt, 'YYYY-MM-DD'), '') AS co_est_dt, COALESCE(a.co_fom, '') AS co_fom, COALESCE(a.co_phn_no, '') AS co_phn_no, COALESCE(a.co_sz_cd, '') AS co_sz_cd, COALESCE(a.co_pals_no, '') AS co_pals_no, COALESCE(a.co_addr, '') AS co_addr, COALESCE(a.co_eml, '') AS co_eml, COALESCE(a.co_hpg_url, '') AS co_hpg_url, COALESCE(a.co_indus, '') AS co_indus, COALESCE(a.co_img_url, '') AS co_img_url, COALESCE(a.co_view_qty, 0) AS co_view_qty, a.cre_usr_id, a.cre_dt, a.upd_usr_id, a.upd_dt, a.co_tp_id, count(*) over() AS ttl_no, b.intg_cd_dp_val_desc AS co_sz_nm, c.co_tp_nm, count(*) over() + 1 - ROW_NUMBER() over(
ORDER BY a.${orderByField} DESC
ORDER BY a.cre_dt DESC, a.co_id
) as no FROM co_mgmt a LEFT JOIN com_intg_cd_dtl b ON ( b.intg_cd = 'CD00009' AND a.co_sz_cd = b.intg_cd_val_ctnt ) LEFT JOIN co_tp_mgmt c ON ( a.co_tp_id = c.co_tp_id ) WHERE 1 = 1
AND a.co_sz_cd = #{coSzCd}
AND UPPER(a.co_nm) LIKE #{coNm}
AND UPPER(a.co_rep_nm) LIKE #{coRepNm}
AND a.co_est_dt >= to_timestamp(#{coEstYrFm}, 'YYYY')
AND a.co_est_dt <= to_timestamp(#{coEstYrTo}, 'YYYY') + INTERVAL '1 year' - INTERVAL '1 second'
AND a.co_tp_id = #{coTpId}
AND UPPER(c.co_tp_nm) LIKE #{coTpNm}
ORDER BY a.${orderByField} DESC
ORDER BY a.cre_dt DESC, a.co_id
OFFSET ${offset}
LIMIT ${limit}

mapper.update:
UPDATE co_mgmt
co_nm = #{coNm}, co_eng_nm = #{coEngNm}, co_biz_no = #{coBizNo}, co_no = #{coNo}, co_rep_nm = #{coRepNm}, co_ttl_emp_no = #{coTtlEmpNo}, co_est_fom = #{coEstFom}, co_est_dt = to_timestamp(#{coEstDt}, 'YYYY-MM-DD'), co_fom = #{coFom}, co_phn_no = #{coPhnNo}, co_sz_cd = #{coSzCd}, co_pals_no = #{coPalsNo}, co_addr = #{coAddr}, co_eml = #{coEml}, co_hpg_url = #{coHpgUrl}, co_indus = #{coIndus}, co_img_url = #{coImgUrl}, co_view_qty = #{coViewQtt}, co_tp_id = #{coTpId}, upd_usr_id = #{updUsrId}, upd_dt = #{updDt},
WHERE co_id = #{coId}

    	UPDATE co_mgmt 
		SET co_view_qty = (
			SELECT COALESCE(co_view_qty, 0) + 1
			FROM co_mgmt 
			WHERE co_id = #{coId}
		)
		WHERE co_id = #{coId}
